<?php
require_once __DIR__.'/../includes/config.php';require_once __DIR__.'/../includes/session.php';if(session_status()===PHP_SESSION_NONE)session_start();if(empty($_SESSION['rider_id'])){header('Location:rider-login.php');exit;}$rid=(int)$_SESSION['rider_id'];function nh($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$rows=[];$has=false;$q=$conn->query("SHOW TABLES LIKE 'notifications'");$has=$q&&$q->num_rows>0;if($has){$st=$conn->prepare("SELECT id,title,message,type,reference_id,is_read,created_at FROM notifications WHERE user_id=? AND role='rider' ORDER BY id DESC LIMIT 100");if($st){$st->bind_param('i',$rid);$st->execute();$rs=$st->get_result();while($x=$rs->fetch_assoc())$rows[]=$x;$st->close();}}if($_SERVER['REQUEST_METHOD']==='POST'&&$has&&isset($_POST['mark_read'])){$nid=(int)$_POST['mark_read'];$st=$conn->prepare("UPDATE notifications SET is_read=1 WHERE id=? AND user_id=? AND role='rider'");if($st){$st->bind_param('ii',$nid,$rid);$st->execute();$st->close();}header('Location:rider-notifications.php');exit;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notifications | Humsafar</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><style>*{box-sizing:border-box}body{margin:0;background:#f7f7f9;font:14px Segoe UI,Arial;color:#222}.page{margin-left:223px;padding:32px;max-width:950px}h1{margin:0;font-size:32px}.sub{color:#777}.notice{background:#fff;border:1px solid #eee;border-radius:14px;padding:18px;margin:14px 0;display:flex;gap:14px}.unread{border-left:4px solid #ed0038;background:#fff8fa}.icon{width:42px;height:42px;border-radius:11px;background:#fff0f4;color:#ed0038;display:flex;align-items:center;justify-content:center;flex-shrink:0}.title{font-weight:850;font-size:15px}.msg{color:#666;margin-top:5px;line-height:1.5}.date{font-size:11px;color:#999;margin-top:7px}.read{border:1px solid #ddd;background:#fff;border-radius:7px;padding:6px 9px;font-size:11px}.empty{text-align:center;color:#888;padding:55px;background:#fff;border:1px solid #eee;border-radius:15px}@media(max-width:900px){.page{margin-left:0;padding:20px}}</style></head><body><?php include __DIR__.'/rider-sidebar.php';?><main class="page"><h1>Notifications</h1><p class="sub">Order assignments and delivery updates.</p><?php if(!$has||!$rows):?><div class="empty"><i class="fa-regular fa-bell" style="font-size:35px;color:#ed0038"></i><p>No notifications yet.</p></div><?php else:foreach($rows as $x):?><div class="notice <?=empty($x['is_read'])?'unread':''?>"><div class="icon"><i class="fa-solid fa-bell"></i></div><div style="flex:1"><div class="title"><?=nh($x['title'])?></div><div class="msg"><?=nh($x['message'])?></div><div class="date"><?=nh(date('d M Y, h:i A',strtotime($x['created_at'])))?></div></div><?php if(empty($x['is_read'])):?><form method="post"><input type="hidden" name="mark_read" value="<?=nh($x['id'])?>"><button class="read" type="submit">Mark read</button></form><?php endif;?></div><?php endforeach;endif;?></main></body></html>